const authorizationHelpTranslations:Record<Locale,string>={
 en_US:'Read-only host truth. Private Testnet execution passes through the automatic Risk Gate into the automatic queue. Unknown, stale, incomplete, unsafe, or uncertain state is rejected, isolated, or paused fail-closed. Legacy approval records are read-only history, not an active workflow.',
 zh_CN:'\u53ea\u8bfb\u5bbf\u4e3b\u771f\u76f8\u3002\u79c1\u4eba Testnet \u6267\u884c\u901a\u8fc7\u81ea\u52a8 Risk Gate \u8fdb\u5165\u81ea\u52a8\u961f\u5217\u3002\u672a\u77e5\u3001\u8fc7\u671f\u3001\u914d\u7f6e\u4e0d\u5b8c\u6574\u3001\u65e0\u6cd5\u8bc1\u660e\u5b89\u5168\u6216\u6267\u884c\u72b6\u6001\u4e0d\u786e\u5b9a\u65f6\uff0c\u7cfb\u7edf\u4f1a\u4ee5 fail-closed \u65b9\u5f0f\u81ea\u52a8\u62d2\u7edd\u3001\u9694\u79bb\u6216\u6682\u505c\u3002\u65e7\u5ba1\u6279\u8bb0\u5f55\u4ec5\u4e3a\u53ea\u8bfb\u5386\u53f2\uff0c\u4e0d\u662f\u6d3b\u52a8\u6d41\u7a0b\u3002',
 zh_TW:'\u552f\u8b80\u5bbf\u4e3b\u771f\u76f8\u3002\u79c1\u4eba Testnet \u57f7\u884c\u901a\u904e\u81ea\u52d5 Risk Gate \u9032\u5165\u81ea\u52d5\u4f47\u5217\u3002\u672a\u77e5\u3001\u904e\u671f\u3001\u8a2d\u5b9a\u4e0d\u5b8c\u6574\u3001\u7121\u6cd5\u8b49\u660e\u5b89\u5168\u6216\u57f7\u884c\u72c0\u614b\u4e0d\u78ba\u5b9a\u6642\uff0c\u7cfb\u7d71\u6703\u4ee5 fail-closed \u65b9\u5f0f\u81ea\u52d5\u62d2\u7d55\u3001\u9694\u96e2\u6216\u66ab\u505c\u3002\u820a\u6838\u51c6\u8a18\u9304\u50c5\u70ba\u552f\u8b80\u6b77\u53f2\uff0c\u4e0d\u662f\u4f5c\u696d\u4e2d\u7684\u6d41\u7a0b\u3002',
 ja_JP:'\u8aad\u307f\u53d6\u308a\u5c02\u7528\u306e\u30db\u30b9\u30c8\u60c5\u5831\u3067\u3059\u3002\u30d7\u30e9\u30a4\u30d9\u30fc\u30c8 Testnet \u5b9f\u884c\u306f\u81ea\u52d5 Risk Gate \u3092\u901a\u904e\u3057\u3066\u81ea\u52d5\u30ad\u30e5\u30fc\u306b\u5165\u308a\u307e\u3059\u3002\u4e0d\u660e\u3001\u671f\u9650\u5207\u308c\u3001\u8a2d\u5b9a\u4e0d\u5b8c\u5168\u3001\u5b89\u5168\u6027\u3092\u8a3c\u660e\u3067\u304d\u306a\u3044\u5834\u5408\u3001\u307e\u305f\u306f\u5b9f\u884c\u72b6\u614b\u304c\u4e0d\u78ba\u5b9f\u306a\u5834\u5408\u306f\u3001fail-closed \u3067\u81ea\u52d5\u7684\u306b\u62d2\u5426\u3001\u9694\u96e2\u3001\u307e\u305f\u306f\u4e00\u6642\u505c\u6b62\u3055\u308c\u307e\u3059\u3002\u65e7\u627f\u8a8d\u8a18\u9332\u306f\u8aad\u307f\u53d6\u308a\u5c02\u7528\u306e\u5c65\u6b74\u3067\u3042\u308a\u3001\u73fe\u884c\u306e\u30ef\u30fc\u30af\u30d5\u30ed\u30fc\u3067\u306f\u3042\u308a\u307e\u305b\u3093\u3002',
 ko_KR:'\uc77d\uae30 \uc804\uc6a9 \ud638\uc2a4\ud2b8 \uc0c1\ud0dc\uc785\ub2c8\ub2e4. \uac1c\uc778 Testnet \uc2e4\ud589\uc740 \uc790\ub3d9 Risk Gate\ub97c \ud1b5\uacfc\ud574 \uc790\ub3d9 \ub300\uae30\uc5f4\ub85c \uc774\ub3d9\ud569\ub2c8\ub2e4. \uc54c \uc218 \uc5c6\uac70\ub098 \uc624\ub798\ub418\uc5c8\uac70\ub098 \uc124\uc815\uc774 \ubd88\uc644\uc804\ud558\uac70\ub098 \uc548\uc804\uc744 \uc785\uc99d\ud560 \uc218 \uc5c6\uac70\ub098 \uc2e4\ud589 \uc0c1\ud0dc\uac00 \ubd88\ud655\uc2e4\ud55c \uacbd\uc6b0 fail-closed \ubc29\uc2dd\uc73c\ub85c \uc790\ub3d9 \uac70\ubd80, \uaca9\ub9ac \ub610\ub294 \uc911\uc9c0\ub429\ub2c8\ub2e4. \uae30\uc874 \uc2b9\uc778 \uae30\ub85d\uc740 \uc77d\uae30 \uc804\uc6a9 \uc774\ub825\uc77c \ubfd0 \ud604\uc7ac \uc6cc\ud06c\ud50c\ub85c\uac00 \uc544\ub2d9\ub2c8\ub2e4.',
 it_IT:'Stato host in sola lettura. Le esecuzioni Testnet private passano dal Risk Gate automatico alla coda automatica. Gli stati sconosciuti, obsoleti, incompleti, non sicuri o incerti vengono rifiutati, isolati o sospesi automaticamente in modalita fail-closed. Le approvazioni precedenti sono cronologia in sola lettura, non un flusso attivo.',
}
export function translate(locale:Locale,key:TranslationKey,values?:Record<string,string|number>){let value=key==='settings.authorizationHelp'?authorizationHelpTranslations[locale]:locale==='en_US'?en_US[key]:roleAuthorizationTranslations[locale][key as RoleAuthorizationKey]??autonomousSettingsTranslations[locale][key as keyof (typeof autonomousSettingsTranslations)[typeof locale]]??authorizationTranslations[locale][key]??notificationTranslations[locale][key]??pageTranslations[locale][key as (typeof explicitlyLocalizedKeys)[number]]??translations[locale][key]??en_US[key];if(values)for(const [name,replacement] of Object.entries(values))value=value.replaceAll(`{${name}}`,String(replacement));return value}
export function dictionaryKeys(locale:Locale){return Object.keys(translations[locale]) as TranslationKey[]}
